args.command:
node -e '
const pricing = {
  vcpu_hr: 0.0335,
  gib_hr: 0.0045,
  spot_discount: 0.70
};

const hours_month = 730;

const workloads_baseline = {
  "payments-api": { replicas: 2, cpu: 0.5, mem_gib: 512/1024, spot: false },
  "image-resizer": { replicas: 3, cpu: 0.5, mem_gib: 256/1024, spot: false },
  "report-builder": { replicas: 2, cpu: 1.0, mem_gib: 1024/1024, spot: false },
  "log-shipper": { replicas: 2, cpu: 0.1, mem_gib: 128/1024, spot: false },
  "session-store": { replicas: 1, cpu: 0.1, mem_gib: 256/1024, spot: false },
};

function calc_cost(workloads, hrs=730) {
  let total_cost = 0;
  let total_cpu = 0;
  let total_mem = 0;
  for (const [name, w] of Object.entries(workloads)) {
    const cpu_total = w.replicas * w.cpu;
    const mem_total = w.replicas * w.mem_gib;
    total_cpu += cpu_total;
    total_mem += mem_total;
    const mult = w.spot ? (1 - pricing.spot_discount) : 1.0;
    const cost = (cpu_total * pricing.vcpu_hr + mem_total * pricing.gib_hr) * hrs * mult;
    console.log(`  ${name}: ${cpu_total.toFixed(2)} vCPU, ${mem_total.toFixed(3)} GiB, spot=${w.spot} -> $${cost.toFixed(2)}`);
    total_cost += cost;
  }
  console.log(`Total: ${total_cpu.toFixed(2)} vCPU, ${total_mem.toFixed(3)} GiB, Cost: $${total_cost.toFixed(2)}`);
  return total_cost;
}

console.log("--- Baseline ---");
const base_cost = calc_cost(workloads_baseline);

console.log("\n--- Rightsized Only (no spot) ---");
const workloads_rightsized = {
  "payments-api": { replicas: 2, cpu: 0.15, mem_gib: 192/1024, spot: false },
  "image-resizer": { replicas: 3, cpu: 0.1, mem_gib: 128/1024, spot: false },
  "report-builder": { replicas: 2, cpu: 0.2, mem_gib: 256/1024, spot: false },
  "log-shipper": { replicas: 2, cpu: 0.1, mem_gib: 128/1024, spot: false },
  "session-store": { replicas: 1, cpu: 0.1, mem_gib: 256/1024, spot: false },
};
const rs_cost = calc_cost(workloads_rightsized);
console.log(`Reduction from rightsizing: ${((1 - rs_cost/base_cost)*100).toFixed(2)}%`);

console.log("\n--- Rightsized + Batch to Spot ---");
const workloads_both = {
  "payments-api": { replicas: 2, cpu: 0.15, mem_gib: 192/1024, spot: false },
  "image-resizer": { replicas: 3, cpu: 0.1, mem_gib: 128/1024, spot: true },
  "report-builder": { replicas: 2, cpu: 0.2, mem_gib: 256/1024, spot: true },
  "log-shipper": { replicas: 2, cpu: 0.1, mem_gib: 128/1024, spot: true },
  "session-store": { replicas: 1, cpu: 0.1, mem_gib: 256/1024, spot: false },
};
const both_cost = calc_cost(workloads_both);
console.log(`Reduction from both: ${((1 - both_cost/base_cost)*100).toFixed(2)}%`);
'
